function makeTemplate(recipe:Recipe,c:Collection,p:Palette,i:number):OriginalTemplate {
  return {id:`original-${c.id}-${recipe.id}`,name:`${c.brand.replaceAll(' & ',' + ').toLowerCase().replace(/\b\w/g,s=>s.toUpperCase())} — ${recipe.name}`,category:recipe.category,width:recipe.width,height:recipe.height,background:p.paper,palette:[p.paper,p.ink,p.accent,p.soft,p.highlight],description:`${recipe.name} for ${c.subject.toLowerCase()}. Original editable typography and vector illustrations; part of the ${c.brand} collection.`,elements:recipe.make(c,p,i),collection:c.brand,composition:recipe.id,provenance:TEMPLATE_PROVENANCE};
}

const MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
function calendar(quarter:number):OriginalTemplate {
  const p=PALETTES[[1,4,5,9][quarter]],year=2027;const elements:DesignElement[]=[label('A LITTLE SPACE FOR WHAT MATTERS',80,60,1280,p,{fontSize:23}),head(`${year}\n${['A fresh start.','Room to grow.','Longer days.','A quiet finish.'][quarter]}`,74,164,1290,302,105,p)];
  for(let j=0;j<3;j++){
    const month=quarter*3+j,y=583+j*448;elements.push(head(MONTHS[month],82,y,1275,78,48,p),rule(83,y+94,1273,p.accent));
    ['MON','TUE','WED','THU','FRI','SAT','SUN'].forEach((day,k)=>elements.push(body(day,89+k*182,y+118,172,46,21,p,{align:'center',fontWeight:700})));
    const offset=(new Date(Date.UTC(year,month,1)).getUTCDay()+6)%7,days=new Date(Date.UTC(year,month+1,0)).getUTCDate();
    for(let d=1;d<=days;d++){const n=offset+d-1;elements.push(body(String(d),89+(n%7)*182,y+181+Math.floor(n/7)*43,172,41,25,p,{align:'center'}));}
  }
  elements.push(label('NOTES / KEEP ONE SMALL THING TO LOOK FORWARD TO',83,1976,1273,p,{fontSize:17}));
  return {id:`original-calendar-2027-quarter-${quarter+1}`,name:`2027 Calendar — ${['Fresh start','Room to grow','Longer days','Quiet finish'][quarter]}`,category:'Calendar',width:1440,height:2036,background:p.paper,palette:[p.paper,p.ink,p.accent,p.soft,p.highlight],description:`An accurate Monday-first ${MONTHS[quarter*3]}–${MONTHS[quarter*3+2]} 2027 calendar with individually editable dates.`,elements,collection:'THE CONSIDERED YEAR',composition:'quarterly-calendar',provenance:TEMPLATE_PROVENANCE};
}

// 18 coherent brand collections × 25 compositions + 4 quarterly calendars = 454.
// Together with the 46 existing originals, the offline catalog contains 500.
export const ORIGINAL_TEMPLATE_LIBRARY:OriginalTemplate[] = COLLECTIONS.flatMap((c,i)=>RECIPES.map(recipe=>makeTemplate(recipe,c,PALETTES[i],i))).concat(Array.from({length:4},(_,i)=>calendar(i)));
export const ORIGINAL_TEMPLATE_STATS = {count:ORIGINAL_TEMPLATE_LIBRARY.length,collections:COLLECTIONS.length+1,compositions:RECIPES.length+1,categories:[...new Set(ORIGINAL_TEMPLATE_LIBRARY.map(t=>t.category))]};
